// Target interface
export interface IPaymentProcessor
{
    void ProcessPayment(decimal amount);
}

// Adaptee (incompatible)
public class LegacyPaymentSystem
{
    public void MakePayment(int amountInCents)
    {
        // Legacy system uses cents
    }
}

// Adapter
public class PaymentAdapter : IPaymentProcessor
{
    private readonly LegacyPaymentSystem _legacy;

    public PaymentAdapter(LegacyPaymentSystem legacy)
    {
        _legacy = legacy;
    }

    public void ProcessPayment(decimal amount)
    {
        _legacy.MakePayment((int)(amount * 100));
    }
}
